   358  struct ResourceMap
   359  {
   360    inline unsigned int get_face_count (void) const
   361    {
   362      unsigned int count = get_type_count ();
   363      for (unsigned int i = 0; i < count; i++)
   364      {
   365        const ResourceTypeRecord& type = get_type_record (i);
   366        if (type.is_sfnt ())
   367          return type.get_resource_count ();
   368      }
   369      return 0;
   370    }
   371
   372    inline const OpenTypeFontFace& get_face (unsigned int idx,
   373                                             const void *data_base) const
   374    {
   375      unsigned int count = get_type_count ();
   376      for (unsigned int i = 0; i < count; i++)
   377      {
   378        const ResourceTypeRecord& type = get_type_record (i);
   379        /* The check for idx < count is here because ResourceRecord is NOT null-safe.
   380         * Because an offset of 0 there does NOT mean null. */
   381        if (type.is_sfnt () && idx < type.get_resource_count ())
   382          return type.get_resource_record (idx, &(this+typeList)).get_face (data_base);
   383      }
   384      return Null (OpenTypeFontFace);
   385    }
   386
   387    inline bool sanitize (hb_sanitize_context_t *c, const void *data_base) const
   388    {
   389      TRACE_SANITIZE (this);
   390      const void *type_base = &(this+typeList);
   391      return_trace (c->check_struct (this) &&
   392                    typeList.sanitize (c, this,
   393                                       type_base,
   394                                       data_base));
   395    }
   396
   397    private:
   398    inline unsigned int get_type_count (void) const { return (this+typeList).lenM1 + 1; }
   399
   400    inline const ResourceTypeRecord& get_type_record (unsigned int i) const
   401    { return (this+typeList)[i]; }
   402
   403    protected:
   404    HBUINT8       reserved0[16];  /* Reserved for copy of resource header */
   405    HBUINT32      reserved1;      /* Reserved for handle to next resource map */
   406    HBUINT16      resreved2;      /* Reserved for file reference number */
   407    HBUINT16      attrs;          /* Resource fork attribute */
   408    OffsetTo<ArrayOfM1<ResourceTypeRecord> >
   409                  typeList;       /* Offset from beginning of map to
   410                                   * resource type list */
   411    Offset16      nameList;       /* Offset from beginning of map to
   412                                   * resource name list */
   413    public:
   414    DEFINE_SIZE_STATIC (28);
   415  };
